 55→// readGeneration reads generation.json from the given tree hash.
 56→// Returns a zero-value GenerationMetadata if the file doesn't exist (new/empty generation).
 57→func (s *V2GitStore) readGeneration(treeHash plumbing.Hash) (GenerationMetadata, error) {
 58→	if treeHash == plumbing.ZeroHash {
 59→		return GenerationMetadata{}, nil
 60→	}
 61→
 62→	tree, err := s.repo.TreeObject(treeHash)
 63→	if err != nil {
 64→		return GenerationMetadata{}, fmt.Errorf("failed to read tree: %w", err)
 65→	}
 66→
 67→	file, err := tree.File(paths.GenerationFileName)
 68→	if err != nil {
 69→		if errors.Is(err, object.ErrFileNotFound) || errors.Is(err, object.ErrEntryNotFound) {
 70→			return GenerationMetadata{}, nil
 71→		}
 72→		return GenerationMetadata{}, fmt.Errorf("failed to find %s in tree: %w", paths.GenerationFileName, err)
 73→	}
 74→
 75→	content, err := file.Contents()
 76→	if err != nil {
 77→		return GenerationMetadata{}, fmt.Errorf("failed to read %s: %w", paths.GenerationFileName, err)
 78→	}
 79→
 80→	var gen GenerationMetadata
 81→	if err := json.Unmarshal([]byte(content), &gen); err != nil {
 82→		return GenerationMetadata{}, fmt.Errorf("failed to parse %s: %w", paths.GenerationFileName, err)
 83→	}
 84→
 85→	return gen, nil
 86→}
 87→
 88→// readGenerationFromRef reads generation.json from the tree pointed to by the given ref.
 89→func (s *V2GitStore) readGenerationFromRef(refName plumbing.ReferenceName) (GenerationMetadata, error) {
 90→	_, treeHash, err := s.getRefState(refName)
 91→	if err != nil {
 92→		return GenerationMetadata{}, fmt.Errorf("failed to get ref state: %w", err)
 93→	}
 94→	return s.readGeneration(treeHash)
 95→}
 96→
 97→// marshalGenerationBlob marshals gen as generation.json and stores it as a git blob.
 98→// Returns a TreeEntry ready to be placed in a tree.
 99→func (s *V2GitStore) marshalGenerationBlob(gen GenerationMetadata) (object.TreeEntry, error) {
100→	data, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
101→	if err != nil {
102→		return object.TreeEntry{}, fmt.Errorf("failed to marshal %s: %w", paths.GenerationFileName, err)
103→	}
104→
105→	blobHash, err := CreateBlobFromContent(s.repo, data)
106→	if err != nil {
107→		return object.TreeEntry{}, fmt.Errorf("failed to create %s blob: %w", paths.GenerationFileName, err)
108→	}
109→
110→	return object.TreeEntry{
111→		Name: paths.GenerationFileName,
112→		Mode: filemode.Regular,
113→		Hash: blobHash,
114→	}, nil
115→}
116→
117→// writeGeneration marshals gen as generation.json and adds the blob entry to entries.
118→func (s *V2GitStore) writeGeneration(gen GenerationMetadata, entries map[string]object.TreeEntry) error {
119→	entry, err := s.marshalGenerationBlob(gen)
120→	if err != nil {
121→		return err
122→	}
123→	entries[paths.GenerationFileName] = entry
124→	return nil
125→}
126→
127→// updateGenerationForWrite reads the current generation metadata, appends the
128→// checkpoint ID (if not already present), and updates timestamps.
129→// Returns the updated metadata for the caller to write into the tree.
130→func (s *V2GitStore) updateGenerationForWrite(rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, now time.Time) (GenerationMetadata, error) {
131→	gen, err := s.readGeneration(rootTreeHash)
132→	if err != nil {
133→		return GenerationMetadata{}, err
134→	}
135→
136→	// Only append if checkpoint ID is not already present (multi-session writes
137→	// to the same checkpoint should not duplicate the ID).
138→	found := false
139→	for _, existing := range gen.Checkpoints {
140→		if existing == checkpointID {
141→			found = true
142→			break
143→		}
144→	}
145→	if !found {
146→		gen.Checkpoints = append(gen.Checkpoints, checkpointID)
147→
148→		// Only update timestamps when a new checkpoint is added, so they reflect
149→		// checkpoint creation times rather than last-write times.
150→		if gen.OldestCheckpointAt.IsZero() {
151→			gen.OldestCheckpointAt = now
152→		}
153→		gen.NewestCheckpointAt = now
154→	}
155→
156→	return gen, nil
157→}
158→
159→// addGenerationToRootTree adds generation.json to an existing root tree, returning
160→// a new root tree hash. Preserves all existing entries (shard directories, etc.).
161→func (s *V2GitStore) addGenerationToRootTree(rootTreeHash plumbing.Hash, gen GenerationMetadata) (plumbing.Hash, error) {
162→	entry, err := s.marshalGenerationBlob(gen)
163→	if err != nil {
164→		return plumbing.ZeroHash, err
165→	}
166→
167→	return UpdateSubtree(s.repo, rootTreeHash, nil, []object.TreeEntry{entry},
168→		UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
169→}
