		return nil
	}

	fetchCmd := exec.CommandContext(ctx, "git", slices.Concat([]string{"fetch", "origin"}, refSpecs)...)
	if fetchOutput, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
