 22→	"github.com/go-git/go-git/v6/plumbing/object"
 23→)
 24→
 25→// pushRefIfNeeded pushes a custom ref to the given target if it exists locally.
 26→// Custom refs (under refs/entire/) don't have remote-tracking refs, so there's
 27→// no "has unpushed" optimization — we always attempt the push and let git handle
 28→// the no-op case.
 29→func pushRefIfNeeded(ctx context.Context, target string, refName plumbing.ReferenceName) error {
 30→	repo, err := OpenRepository(ctx)
 31→	if err != nil {
 32→		return nil //nolint:nilerr // Hook must be silent on failure
 33→	}
 34→
 35→	if _, err := repo.Reference(refName, true); err != nil {
 36→		return nil //nolint:nilerr // Ref doesn't exist locally, nothing to push
 37→	}
 38→
 39→	return doPushRef(ctx, target, refName)
 40→}
 41→
 42→// tryPushRef attempts to push a custom ref using an explicit refspec.
 43→func tryPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
 44→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
 45→	defer cancel()
 46→
 47→	// Use --no-verify to prevent recursive hook calls (this runs inside pre-push)
 48→	refSpec := fmt.Sprintf("%s:%s", refName, refName)
 49→	cmd := exec.CommandContext(ctx, "git", "push", "--no-verify", target, refSpec)
 50→	cmd.Stdin = nil // Disconnect stdin to prevent hanging in hook context
 51→
 52→	output, err := cmd.CombinedOutput()
 53→	if err != nil {
 54→		if strings.Contains(string(output), "non-fast-forward") ||
 55→			strings.Contains(string(output), "rejected") {
 56→			return errors.New("non-fast-forward")
 57→		}
 58→		return fmt.Errorf("push failed: %s", output)
 59→	}
 60→	return nil
 61→}
 62→
 63→// doPushRef pushes a custom ref with fetch+merge recovery on conflict.
 64→func doPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
 65→	displayTarget := target
 66→	if isURL(target) {
 67→		displayTarget = "checkpoint remote"
 68→	}
 69→
 70→	shortRef := shortRefName(refName)
 71→	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
 72→	stop := startProgressDots(os.Stderr)
 73→
 74→	if err := tryPushRef(ctx, target, refName); err == nil {
 75→		stop(" done")
 76→		return nil
 77→	}
 78→	stop("")
 79→
 80→	fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", shortRef)
 81→	stop = startProgressDots(os.Stderr)
 82→
 83→	if err := fetchAndMergeRef(ctx, target, refName); err != nil {
 84→		stop("")
 85→		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", shortRef, err)
 86→		printCheckpointRemoteHint(target)
 87→		return nil
 88→	}
 89→	stop(" done")
 90→
 91→	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
 92→	stop = startProgressDots(os.Stderr)
 93→
 94→	if err := tryPushRef(ctx, target, refName); err != nil {
 95→		stop("")
 96→		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", shortRef, err)
 97→		printCheckpointRemoteHint(target)
 98→	} else {
 99→		stop(" done")
100→	}
101→
102→	return nil
103→}
104→
105→// fetchAndMergeRef fetches a remote custom ref and merges it into the local ref.
106→// Uses the same tree-flattening merge as v1 (sharded paths are unique, so no conflicts).
107→//
108→// For /full/current: if the remote has archived generations not present locally,
109→// another machine rotated. In that case, local data is merged into the latest
110→// archived generation instead of into /full/current (see handleRotationConflict).
111→func fetchAndMergeRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
112→	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
113→	defer cancel()
114→
115→	// Fetch to a temp ref
116→	tmpRefSuffix := strings.ReplaceAll(string(refName), "/", "-")
117→	tmpRefName := plumbing.ReferenceName("refs/entire-fetch-tmp/" + tmpRefSuffix)
118→	refSpec := fmt.Sprintf("+%s:%s", refName, tmpRefName)
119→
120→	fetchCmd := exec.CommandContext(ctx, "git", "fetch", target, refSpec)
121→	if output, err := fetchCmd.CombinedOutput(); err != nil {
122→		return fmt.Errorf("fetch failed: %s", output)
123→	}
124→
125→	repo, err := OpenRepository(ctx)
126→	if err != nil {
127→		return fmt.Errorf("failed to open repository: %w", err)
128→	}
129→
130→	// Check for rotation conflict on /full/current
131→	if string(refName) == paths.V2FullCurrentRefName {
132→		remoteOnlyArchives, detectErr := detectRemoteOnlyArchives(ctx, target, repo)
133→		if detectErr == nil && len(remoteOnlyArchives) > 0 {
134→			err := handleRotationConflict(ctx, target, repo, refName, tmpRefName, remoteOnlyArchives)
135→			_ = repo.Storer.RemoveReference(tmpRefName) //nolint:errcheck // cleanup is best-effort
136→			return err
137→		}
138→	}
139→
140→	// Standard tree merge (no rotation detected)
141→	localRef, err := repo.Reference(refName, true)
142→	if err != nil {
143→		return fmt.Errorf("failed to get local ref: %w", err)
144→	}
145→	localCommit, err := repo.CommitObject(localRef.Hash())
146→	if err != nil {
147→		return fmt.Errorf("failed to get local commit: %w", err)
148→	}
149→	localTree, err := localCommit.Tree()
150→	if err != nil {
151→		return fmt.Errorf("failed to get local tree: %w", err)
152→	}
153→
154→	remoteRef, err := repo.Reference(tmpRefName, true)
155→	if err != nil {
156→		return fmt.Errorf("failed to get remote ref: %w", err)
157→	}
158→	remoteCommit, err := repo.CommitObject(remoteRef.Hash())
159→	if err != nil {
160→		return fmt.Errorf("failed to get remote commit: %w", err)
161→	}
162→	remoteTree, err := remoteCommit.Tree()
163→	if err != nil {
164→		return fmt.Errorf("failed to get remote tree: %w", err)
165→	}
166→
167→	entries := make(map[string]object.TreeEntry)
168→	if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
169→		return fmt.Errorf("failed to flatten local tree: %w", err)
170→	}
171→	if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
172→		return fmt.Errorf("failed to flatten remote tree: %w", err)
173→	}
174→
175→	mergedTreeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
176→	if err != nil {
177→		return fmt.Errorf("failed to build merged tree: %w", err)
178→	}
179→
180→	mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
181→		[]plumbing.Hash{localRef.Hash(), remoteRef.Hash()},
182→		"Merge remote "+shortRefName(refName))
183→	if err != nil {
184→		return fmt.Errorf("failed to create merge commit: %w", err)
185→	}
186→
187→	newRef := plumbing.NewHashReference(refName, mergeCommitHash)
188→	if err := repo.Storer.SetReference(newRef); err != nil {
189→		return fmt.Errorf("failed to update ref: %w", err)
190→	}
191→
192→	_ = repo.Storer.RemoveReference(tmpRefName) //nolint:errcheck // cleanup is best-effort
193→	return nil
194→}
195→
196→// generationRefPattern matches the 13-digit archived generation ref suffix format.
197→var generationRefPattern = regexp.MustCompile(`^\d{13}$`)
